224		}
225		if !strings.Contains(msg, "link.conf") {
226			t.Errorf("expected the diagnostic to name the import statement's target, got: %v", err)
227		}
228	}
229	
230	// A multi-file loop closing through a symlink alias must report the full
231	// chain of files involved.
232	func TestImportCycleChainThroughSymlink(t *testing.T) {
233		dir := t.TempDir()
234		a := filepath.Join(dir, "a.conf")
235		writeImportFile(t, a, "import b.conf\n")
236		writeImportFile(t, filepath.Join(dir, "b.conf"), "import link.conf\n")
237		symlinkOrSkip(t, a, filepath.Join(dir, "link.conf"))
238	
239		_, err := parseInDir(t, dir, "import "+a+"\n")
240		if err == nil {
241			t.Fatal("expected a cycle error, got nil")
242		}
243		msg := err.Error()
244		for _, want := range []string{"a.conf", "b.conf", "link.conf"} {
245			if !strings.Contains(msg, want) {
246				t.Errorf("expected diagnostic to contain %q, got: %v", want, err)
247			}
248		}
249		// the chain closes back to its start
250		chain := strings.SplitN(msg, " (while", 2)[0]
251		if !strings.HasPrefix(chain, "import cycle detected: ") {
252			t.Errorf("expected a cycle-chain prefix, got: %v", err)
253		}
254		if !strings.HasSuffix(chain, "a.conf") {
255			t.Errorf("expected the chain to loop back to a.conf, got: %v", err)
256		}
257	}
258	
259	// A loop formed purely by ".." spellings must be detected even though
260	// the lexical paths differ in writing.
261	func TestImportCycleThroughDotDot(t *testing.T) {
262		dir := t.TempDir()
263		a := filepath.Join(dir, "proj", "a.conf")
264		b := filepath.Join(dir, "proj", "sub", "b.conf")
265		writeImportFile(t, a, "import sub/b.conf\n")
266		writeImportFile(t, b, "import ../a.conf\n")
267	
268		_, err := parseInDir(t, dir, "import "+a+"\n")
269		if err == nil {
270			t.Fatal("expected a cycle error, got nil")
271		}
272		msg := err.Error()
273		if !strings.Contains(msg, "cycle") || !strings.Contains(msg, "a.conf") || !strings.Contains(msg, "b.conf") {
274			t.Errorf("expected a chain naming a.conf and b.conf, got: %v", err)
275		}
276	}
277	
278	// The classic recursive self-import still fails, through the new chained
279	// diagnostic.
280	func TestImportRecursiveCycleChain(t *testing.T) {
281		dir := t.TempDir()
282		a := filepath.Join(dir, "a.conf")
283		writeImportFile(t, a, "import a.conf\n")
284	
285		_, err := parseInDir(t, dir, "import "+a+"\n")
286		if err == nil {
287			t.Fatal("expected a cycle error, got nil")
288		}
289		if !strings.Contains(err.Error(), "cycle") {
290			t.Errorf("expected a cycle diagnostic, got: %v", err)
291		}
292	}
293	
294	// The same regular file imported at distinct points of a diamond-shaped
295	// graph is not a cycle and must succeed. It expands once per explicit
296	// import statement.
297	func TestImportDiamondSameFileNotCycle(t *testing.T) {
298		dir := t.TempDir()
299		writeImportFile(t, filepath.Join(dir, "d.conf"), site("host-d"))
300		writeImportFile(t, filepath.Join(dir, "b.conf"), "import d.conf\n")
301		writeImportFile(t, filepath.Join(dir, "c.conf"), "import d.conf\n")
302		writeImportFile(t, filepath.Join(dir, "a.conf"), "import b.conf\nimport c.conf\n")
303	
304		blocks, err := parseInDir(t, dir, "import "+filepath.Join(dir, "a.conf")+"\n")
305		if err != nil {
306			t.Fatalf("expected a shared leaf not to be a cycle, got: %v", err)
307		}
308	
309		got := blockKeys(blocks)
310		if len(got) != 2 || got[0] != "host-d" || got[1] != "host-d" {
311			t.Errorf("expected two host-d expansions, got %v", got)
312		}
313	}
314	
315	// Directories remain an error using the existing category.
316	func TestImportDirectoryStillErrors(t *testing.T) {
317		dir := t.TempDir()
318		sub := filepath.Join(dir, "subdir")
319		if err := os.Mkdir(sub, 0o755); err != nil {
320			t.Fatal(err)
321		}
322		_, err := parseInDir(t, dir, "import "+sub+"\n")
323		if err == nil {
324			t.Fatal("expected an error importing a directory, got nil")
325		}
326		if !strings.Contains(err.Error(), "is a directory") {
327			t.Errorf("expected a directory error category, got: %v", err)
328		}
329	}
330	
331	// A glob matching nothing is still a non-error; an explicit missing file
332	// is still an error.
333	func TestImportNoMatchCategories(t *testing.T) {
334		dir := t.TempDir()
335		if _, err := parseInDir(t, dir, "import "+filepath.Join(dir, "nope", "*.conf")+"\n"); err != nil {
336			t.Errorf("expected a non-matching glob to be a non-error, got: %v", err)
337		}
338		if _, err := parseInDir(t, dir, "import "+filepath.Join(dir, "nope", "file.conf")+"\n"); err == nil {
339			t.Error("expected a missing explicit file to be an error, got nil")
340		}
341	}
342	
343	// Repeatedly adapting the same file tree yields identical expansion
344	// order; a cycle yields the identical error chain.
345	func TestImportDeterministicAcrossRuns(t *testing.T) {
346		dir := t.TempDir()
347		writeImportFile(t, filepath.Join(dir, "a.conf"), site("host-a"))
348		writeImportFile(t, filepath.Join(dir, "m.conf"), site("host-m"))
349		symlinkOrSkip(t, filepath.Join(dir, "a.conf"), filepath.Join(dir, "z-alias.conf"))
350		root := filepath.Join(dir, "Caddyfile")
351		body := []byte("import " + filepath.Join(dir, "*") + "\n")
352	
353		var first []string
354		for run := 0; run < 3; run++ {
355			blocks, err := Parse(root, body)
356			if err != nil {
357				t.Fatalf("run %d: expected no error, got: %v", run, err)
358			}
359			keys := blockKeys(blocks)
360			if first == nil {
361				first = keys
362				continue
363			}
364			if strings.Join(keys, ",") != strings.Join(first, ",") {
365				t.Errorf("run %d: expected %v, got %v", run, first, keys)
366			}
367		}
368	
369		// error chain stability
370		cyc := filepath.Join(dir, "cyc.conf")
371		writeImportFile(t, cyc, "import link2.conf\n")
372		symlinkOrSkip(t, cyc, filepath.Join(dir, "link2.conf"))
373		cycleBody := []byte("import " + cyc + "\n")
374		var firstErr string
375		for run := 0; run < 3; run++ {
376			_, err := Parse(root, cycleBody)
377			if err == nil {
378				t.Fatalf("run %d: expected a cycle error, got nil", run)
379			}
380			if firstErr == "" {
381				firstErr = err.Error()
382				continue
383			}
384			if err.Error() != firstErr {
385				t.Errorf("run %d: expected identical error\nwant: %s\ngot:  %s", run, firstErr, err.Error())
386			}
387		}
388	}
389	
390	// Exercise the public Adapter.Adapt entry point: a glob that hits the
391	// same real file through an alias expands it once and succeeds, while a
392	// cycle means the whole adaptation fails (the caller never receives a
393	// partially expanded successful result).
394	func TestAdapterImportResolution(t *testing.T) {
395		dir := t.TempDir()
396		root := filepath.Join(dir, "Caddyfile")
397		writeImportFile(t, filepath.Join(dir, "a.conf"), site("host-a"))
398		writeImportFile(t, filepath.Join(dir, "m.conf"), site("host-m"))
399		symlinkOrSkip(t, filepath.Join(dir, "a.conf"), filepath.Join(dir, "z-alias.conf"))
400	
401		var captured []ServerBlock
402		adapter := Adapter{ServerType: captureServerType{blocks: &captured}}
403	
404		// success: alias + real file collapsed, order follows real paths
405		out, _, err := adapter.Adapt([]byte("import "+filepath.Join(dir, "*")+"\n"),
406			map[string]any{"filename": root})
407		if err != nil {
408			t.Fatalf("expected successful adaptation, got: %v", err)
409		}
410		if len(out) == 0 {
411			t.Error("expected non-empty JSON output, got empty")
412		}
413		if got := blockKeys(captured); strings.Join(got, ",") != "host-a,host-m" {
414			t.Errorf("expected hosts [host-a host-m], got %v", got)
415		}
416	
417		// failure: any imported file triggering a cycle fails the whole adapt
418		cyc := filepath.Join(dir, "cyc.conf")
419		writeImportFile(t, cyc, "import alias2.conf\n")
420		symlinkOrSkip(t, cyc, filepath.Join(dir, "alias2.conf"))
421		captured = nil
422		out, _, err = adapter.Adapt([]byte("import "+cyc+"\n"),
423			map[string]any{"filename": root})
424		if err == nil {
425			t.Fatal("expected the whole adaptation to fail on a cycle, got nil")
426		}
427		if out != nil {
428			t.Errorf("expected no partial result on failure (got %d bytes)", len(out))
429		}
430		if captured != nil {
431			t.Errorf("expected Setup not to run on a failed expansion (partial result)")
432		}
433		if !strings.Contains(err.Error(), "cycle") {
434			t.Errorf("expected a cycle diagnostic, got: %v", err)
435		}
436	}
437	
438	// A dangling symlink keeps the existing "not found / could not import"
439	// error category rather than surfacing a path-resolution error.
440	func TestAdapterDanglingSymlinkCategory(t *testing.T) {
441		dir := t.TempDir()
442		root := filepath.Join(dir, "Caddyfile")
443		symlinkOrSkip(t, filepath.Join("does-not-exist"), filepath.Join(dir, "dangling.conf"))
444	
445		var captured []ServerBlock
446		adapter := Adapter{ServerType: captureServerType{blocks: &captured}}
447		_, _, err := adapter.Adapt([]byte("import "+filepath.Join(dir, "dangling.conf")+"\n"),
448			map[string]any{"filename": root})
449		if err == nil {
450			t.Fatal("expected an error for a dangling symlink, got nil")
451		}
452		if strings.Contains(err.Error(), "Could not resolve import") {
453			t.Errorf("dangling symlink should keep existing I/O error category, got: %v", err)
454		}
455	}
