package caddyfile

import (
	"os"
	"path/filepath"
	"sync"
)

// Case sensitivity of path comparisons is a property of the filesystem a
// file resides on, not of the operating system or build target: a
// case-insensitive volume may be mounted on a Unix host (for example the
// default macOS data volume) and a case-sensitive volume on Windows. It is
// therefore observed at runtime against the directory in question rather
// than fixed with a build tag.

// dirCaseSensitivity memoizes probe results per directory; each entry is a
// *caseSensitivityProbe so concurrent first lookups share a single probe.
var dirCaseSensitivity sync.Map

type caseSensitivityProbe struct {
	once      sync.Once
	sensitive bool
}

// fsCaseSensitive reports whether identity comparisons under dir are
// case-sensitive. dir should be an existing directory; when it cannot be
// probed it conservatively reports case-sensitive, which only disables
// case folding and never masks a real I/O error.
func fsCaseSensitive(dir string) bool {
	v, _ := dirCaseSensitivity.LoadOrStore(dir, &caseSensitivityProbe{})
	probe := v.(*caseSensitivityProbe)
	probe.once.Do(func() {
		probe.sensitive = probeCaseSensitive(dir)
	})
	return probe.sensitive
}

// probeCaseSensitive creates a throwaway file whose name contains an ASCII
// letter and checks whether the same name with that letter's case flipped
// addresses the same file. Flipping onto the same inode means the
// filesystem ignores case; a missing flipped name means it does not.
func probeCaseSensitive(dir string) bool {
	f, err := os.CreateTemp(dir, ".caddy-case-*")
	if err != nil {
		return true
	}
	origName := f.Name()
	f.Close()
	defer os.Remove(origName)

	flippedName := filepath.Join(dir, flipLetter(filepath.Base(origName)))
	origInfo, err := os.Stat(origName)
	if err != nil {
		return true
	}
	flippedInfo, err := os.Stat(flippedName)
	if err != nil {
		return true
	}
	return !os.SameFile(origInfo, flippedInfo)
}

// flipLetter returns name with the case of its first ASCII letter toggled,
// or name unchanged when it contains no letter.
func flipLetter(name string) string {
	for i, r := range name {
		switch {
		case r >= 'a' && r <= 'z':
			return name[:i] + string(r-'a'+'A') + name[i+1:]
		case r >= 'A' && r <= 'Z':
			return name[:i] + string(r-'A'+'a') + name[i+1:]
		}
	}
	return name
}

