// doSingleImport lexes the individual file at importFile and returns
// its tokens or an error, if any.
func (p *parser) doSingleImport(importFile string) ([]Token, error) {
	// Stat before opening: opening a non-regular target such as a FIFO or
	// device node can block indefinitely or read without end. Stat follows
	// symlinks, so a dangling alias simply fails as an unreadable file.
	info, err := os.Stat(importFile)
	var file *os.File
	if err != nil {
		// Keep the established "Could not import" I/O error category (and
		// its errno) for missing and unreadable files by attempting the
		// open anyway. This cannot block: targets that block on open, such
		// as FIFOs, stat successfully and are rejected below instead.
		file, err = os.Open(importFile)
		if err != nil {
			return nil, p.Errf("Could not import %s: %v", importFile, err)
		}
		defer file.Close()
		info, err = file.Stat()
		if err != nil {
			return nil, p.Errf("Could not import %s: %v", importFile, err)
		}
	}
	switch {
	case info.IsDir():
		return nil, p.Errf("Could not import %s: is a directory", importFile)
	case !info.Mode().IsRegular():
		return nil, p.Errf("Could not import %s: not a regular file", importFile)
	}
	if file == nil {
		file, err = os.Open(importFile)
		if err != nil {
			return nil, p.Errf("Could not import %s: %v", importFile, err)
		}
		defer file.Close()
	}

	input, err := io.ReadAll(file)
	if err != nil {
		return nil, p.Errf("Could not read imported file %s: %v", importFile, err)
	}

