func TestScratchCaseProbe(t *testing.T) {
	dir := t.TempDir()
	t.Logf("dir=%s caseSensitive=%v", dir, probeCaseSensitive(dir))

	// glob hits the same file through two case spellings
	writeImportFile(t, filepath.Join(dir, "a.conf"), site("host-a"))
	writeImportFile(t, filepath.Join(dir, "m.conf"), site("host-m"))
	blocks, err := parseInDir(t, dir, "import "+filepath.Join(dir, "*")+"\n")
	if err != nil {
