	t.Logf("glob keys=%v", blockKeys(blocks))

	// cycle through a case-only alias
	c := filepath.Join(dir, "cyc.conf")
	writeImportFile(t, c, "import CYC.CONF\n")
	_, err = parseInDir(t, dir, "import "+c+"\n")
	t.Logf("case-alias cycle err=%v", err)
}

