688	// target, since a single host can mount both kinds of volumes.
689	//
690	// If a path cannot be fully evaluated (for example a dangling symlink),
691	// it falls back to the cleaned absolute path; the subsequent open in
692	// doSingleImport then reports the underlying I/O error using the
693	// existing error paths.
694	func (p *parser) realPath(path string) (string, error) {
695		if p.realPathCache == nil {
696			p.realPathCache = make(map[string]string)
697		}
698		if cached, ok := p.realPathCache[path]; ok {
699			return cached, nil
700		}
701	
702		abs, err := caddy.FastAbs(path)
703		if err != nil {
704			return "", err
705		}
706	
707		// Resolve symlinks to obtain the real file identity. If the path
708		// cannot be fully evaluated (a dangling symlink, a permission error,
709		// ...), fall back to the cleaned absolute path: the subsequent open
710		// in doSingleImport then reports the underlying I/O error using the
711		// existing error paths, so unreadable imports keep their established
712		// error categories.
713		real := abs
714		if resolved, err := filepath.EvalSymlinks(abs); err == nil {
715			real = filepath.Clean(resolved)
716		}
717		if !p.isCaseSensitive(filepath.Dir(real)) {
718			real = strings.ToLower(real)
719		}
720	
721		p.realPathCache[path] = real
722		return real, nil
723	}
724	
725	// isCaseSensitive reports whether path identity under dir is
726	// case-sensitive, probing the directory once per parse and reusing the
727	// result.
728	func (p *parser) isCaseSensitive(dir string) bool {
729		if p.caseSensitivityCache == nil {
730			p.caseSensitivityCache = make(map[string]bool)
731		}
732		if sensitive, probed := p.caseSensitivityCache[dir]; probed {
733			return sensitive
734		}
735		sensitive := probeCaseSensitive(dir)
736		p.caseSensitivityCache[dir] = sensitive
737		return sensitive
738	}
739	
740	// doSingleImport lexes the individual file at importFile and returns
741	// its tokens or an error, if any.
742	func (p *parser) doSingleImport(importFile string) ([]Token, error) {
743		// Stat before opening: opening a non-regular target such as a FIFO or
744		// device node can block indefinitely or read without end. Stat follows
745		// symlinks, so a dangling alias fails as an unreadable file using the
746		// established "Could not import" error category.
747		info, err := os.Stat(importFile)
748		if err != nil {
749			return nil, p.Errf("Could not import %s: %v", importFile, err)
750		}
751		switch {
752		case info.IsDir():
753			return nil, p.Errf("Could not import %s: is a directory", importFile)
754		case !info.Mode().IsRegular():
755			return nil, p.Errf("Could not import %s: not a regular file", importFile)
756		}
757	
758		file, err := os.Open(importFile)
759		if err != nil {
760			return nil, p.Errf("Could not import %s: %v", importFile, err)
761		}
762		defer file.Close()
763	
764		input, err := io.ReadAll(file)
765		if err != nil {
766			return nil, p.Errf("Could not read imported file %s: %v", importFile, err)
767		}
768	
769		// only warning in case of empty files
770		if len(input) == 0 || len(strings.TrimSpace(string(input))) == 0 {
771			caddy.Log().Warn("Import file is empty", zap.String("file", importFile))
772			return []Token{}, nil
773		}
774	
775		importedTokens, err := allTokens(importFile, input)
776		if err != nil {
777			return nil, p.Errf("Could not read tokens while importing %s: %v", importFile, err)
778		}
779	
780		// Tack the file path onto these tokens so errors show the imported file's name
781		// (we use full, absolute path to avoid bugs: issue #1892). Use the canonical,
782		// symlink-resolved path: relative imports inside an imported file must resolve
783		// relative to the file that actually declares them, even when it was reached
784		// through a symlink alias or a path containing "..".
785		filename, err := p.realPath(importFile)
786		if err != nil {
787			return nil, p.Errf("Failed to get absolute path of file: %s: %v", importFile, err)
788		}
789		for i := range importedTokens {
790			importedTokens[i].File = filename
791		}
792	
793		return importedTokens, nil
794	}
