798	// It expects the currently-loaded token to be a directive
799	// (or } that ends a server block). The collected tokens
800	// are loaded into the current server block for later use
801	// by directive setup functions.
802	func (p *parser) directive() error {
803		// a segment is a list of tokens associated with this directive
804		var segment Segment
805	
806		// the directive itself is appended as a relevant token
807		segment = append(segment, p.Token())

