package caddyfile

import (
	"path/filepath"
	"testing"
)

func TestScratchLabelCase(t *testing.T) {
	dir := t.TempDir()
	t.Logf("caseSensitive=%v", probeCaseSensitive(dir))
	c := filepath.Join(dir, "cyc.conf")
	writeImportFile(t, c, "import CYC.CONF\n")
	_, err := parseInDir(t, dir, "import "+c+"\n")
	t.Logf("err=%v", err)

	// case-only glob alias dedup
	writeImportFile(t, filepath.Join(dir, "a.conf"), site("host-a"))
	writeImportFile(t, filepath.Join(dir, "m.conf"), site("host-m"))
	b, err := parseInDir(t, dir, "import "+filepath.Join(dir, "*.conf")+"\n")
	if err != nil {
		t.Fatal(err)
	}
	t.Logf("glob=%v", blockKeys(b))
}

